// «Test your knowledge»: 100 questions in English and Spanish about the hardware left behind and the
// worlds it explores. In each list of options the FIRST one is the correct answer; the quiz shuffles
// them when it shows the question. `go` is the place to visit in 3D after answering.
import type { GuidedTourTarget } from './guidedToursData';

export interface QuizText {
  q: string;
  /** options[0] is the correct answer */
  options: [string, string, string, string];
  explain: string;
}

export interface QuizQuestion {
  id: string;
  go?: GuidedTourTarget;
  es: QuizText;
  en: QuizText;
}

type T = [string, [string, string, string, string], string];
const m = (missionId: string): GuidedTourTarget => ({ kind: 'mission', missionId });
const b = (bodyId: Extract<GuidedTourTarget, { kind: 'body' }>['bodyId']): GuidedTourTarget => ({ kind: 'body', bodyId });
const moon = (bodyId: Extract<GuidedTourTarget, { kind: 'moon' }>['bodyId'], moonId: string): GuidedTourTarget => ({
  kind: 'moon',
  bodyId,
  moonId,
});
const d = (id: Extract<GuidedTourTarget, { kind: 'deepspace' }>['id']): GuidedTourTarget => ({ kind: 'deepspace', id });
const Q = (id: string, go: GuidedTourTarget | undefined, es: T, en: T): QuizQuestion => ({
  id,
  go,
  es: { q: es[0], options: es[1], explain: es[2] },
  en: { q: en[0], options: en[1], explain: en[2] },
});

